Unstained <- TheUnstained

Panel <- file.path("data", "Panel.csv")
Panel <- read.csv(Panel, check.names=FALSE) |> dplyr::filter(Day %in% c(1,2,3,4,5))
GT <- FluorophoreMatrix(data=Panel, NumberDetectors = 38)
